xml.Script:
        W := 0.5;
 
        AngleX :=   0 * Pi / 180;
        AngleY :=  45 * Pi / 180;
        AngleZ := -45 * Pi / 180;

        procedure Rotate(i);
        begin
            temp := y[i] * cos(AngleX) - z[i] * sin(AngleX);
            z[i] := y[i] * sin(AngleX) + z[i] * cos(AngleX);
            y[i] := temp;

            temp := z[i] * cos(AngleY) - x[i] * sin(AngleY);
            x[i] := z[i] * sin(AngleY) + x[i] * cos(AngleY);
            z[i] := temp;

            temp := x[i] * cos(AngleZ) - y[i] * sin(AngleZ);
            y[i] := x[i] * sin(AngleZ) + y[i] * cos(AngleZ);
            x[i] := temp;
        end;

        // initial axes
        x[0] := 0; y[0] := 1; z[0] := 1;
        x[1] := 0; y[1] :=-1; z[1] := 1;
        x[2] := 1; y[2] := 0; z[2] := 1;
        x[3] := 1; y[3] := 0; z[3] :=-1;
        x[4] := 1; y[4] := 1; z[4] := 0;
        x[5] :=-1; y[5] := 1; z[5] := 0;

        for i := 0 to 5 do
            Rotate(i);
